package com.lims.model;
public class InventoryOption {private int inventoryId,productId;private String productCode,productName,serialNumber,location;public int getInventoryId(){return inventoryId;}public void setInventoryId(int v){inventoryId=v;}public int getProductId(){return productId;}public void setProductId(int v){productId=v;}public String getProductCode(){return productCode;}public void setProductCode(String v){productCode=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public String getSerialNumber(){return serialNumber;}public void setSerialNumber(String v){serialNumber=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}}
